  at_scale: 'at scale',
  aup: 'Acceptable Use Policy',
  aup_intro:
    "This Acceptable Use Policy (this 'Policy') outlines prohibited uses of the web services offered by Capgo and its affiliates (the 'Services') and the website located at https://capgo.app (the 'Capgo Site'). The examples in this Policy are not exhaustive. We may modify this Policy at any time by posting a revised version on the Capgo Site. By using the Services or accessing the Capgo Site, you agree to the latest version of this Policy. If you violate the Policy or authorize or help others to do so, we may suspend or terminate your use of the Services.",
  aup_monitoring_enforcement: 'Our Monitoring and Enforcement',
  aup_monitoring_enforcement_desc:
    'We reserve the right, but do not assume the obligation, to investigate any violation of this Policy or misuse of the Services or Capgo Site. We may:',
  aup_no_email_abuse: 'No E-Mail or Other Message Abuse',
  aup_no_email_abuse_desc:
    "You will not distribute, publish, send, or facilitate the sending of unsolicited mass e-mail or other messages, promotions, advertising, or solicitations (like 'spam'), including commercial advertising and informational announcements. You will not alter or obscure mail headers or assume a sender's identity without the sender's explicit permission. You will not collect replies to messages sent from another internet service provider if those messages violate this Policy or the acceptable use policy of that provider.",
  aup_no_illegal_use: 'No Illegal, Harmful, or Offensive Use or Content',
  aup_no_illegal_use_desc:
    'You may not use, or encourage, promote, facilitate or instruct others to use, the Services or Capgo Site for any illegal, harmful, fraudulent, infringing or offensive use, or to transmit, store, display, distribute or otherwise make available content that is illegal, harmful, fraudulent, infringing or offensive. Prohibited activities or content include:',
  aup_no_network_abuse: 'No Network Abuse',
  aup_no_network_abuse_desc:
    'You may not make network connections to any users, hosts, or networks unless you have permission to communicate with them. Prohibited activities include:',
  aup_no_security_violations: 'No Security Violations',
  aup_no_security_violations_desc:
    "You may not use the Services to violate the security or integrity of any network, computer or communications system, software application, or network or computing device (each, a 'System'). Prohibited activities include:",
  aup_reporting_violations: 'Reporting of Violations of this Policy',
  aup_reporting_violations_desc:
    'If you become aware of any violation of this Policy, you will immediately notify us and provide us with assistance, as requested, to stop or remedy the violation. To report any violation of this Policy, please contact us at support@capgo.app.',
