  discover_ready_plugins: 'Ship auth, payments, biometrics, background tasks, and SDK wrappers without rebuilding the native bridge from scratch.',
  do_you_have_purchasing_power_parity_pricing: 'Do you have Purchasing Power Parity (PPP) pricing?',
