  explainer_next_launch_step_1: 'A bug in the web layer is live. Users hit it right now.',
  explainer_next_launch_step_2: 'You fix it and run one command. Capgo signs and publishes bundle 1.0.1.',
  explainer_next_launch_step_3: 'The app checks Capgo and downloads the bundle in the background. Nothing interrupts the user.',
  explainer_next_launch_step_4: 'The user leaves the app. The new bundle waits, ready for the next launch.',
  explainer_next_launch_step_5: 'Next launch opens 1.0.1. The fix is live without a store review.',
  explainer_next_launch_step_6: 'The app calls notifyAppReady(). If it never does, Capgo rolls back to the last working bundle.',
