  explainer_ota_step_1: 'A Capacitor app has two layers: the web layer (JS, CSS, HTML, assets) and the native shell (Swift, Kotlin, plugins).',
  explainer_ota_step_2: 'A web-layer change ships as a live update. The CLI checks it is OTA-safe before upload.',
  explainer_ota_step_3: 'A native change is stopped. The CLI tells you it needs a new binary through store review.',
