  live_update_eas_eyebrow: 'Coming from Expo?',
  live_update_eas_title: 'The EAS Update equivalent for Capacitor apps',
  live_update_eas_lead:
    'EAS Update ships JavaScript fixes for Expo and React Native apps. Capgo does the same job for Capacitor web bundles: channels, rollback, and device logs. Stay on EAS if the app is React Native. Use Capgo if you kept the web UI.',
  live_update_eas_cta: 'Compare Capgo with Expo Application Services',

  live_update_decision_1: 'You need a recovery path for production bugs that does not depend on App Store or Play review time.',
  live_update_decision_2: 'Your app has multiple customer cohorts, white-label deployments, beta testers, or support-only debug channels.',
  live_update_decision_3: 'Your team needs compliance-friendly control: signed bundles, rollback, auditability, and a self-hosting path.',
  live_update_decision_title: 'Choose live updates when these statements are true',
  live_update_cta_subtitle: 'Start automatic in 5 minutes. Switch to manual control when your release strategy needs it.',
  live_update_cta_title: 'Ship your next fix today.',
  live_update_delta_command: 'Upload with delta updates enabled',
  live_update_delta_desc:
    'Traditional updates download the entire bundle every time. With delta updates, devices only download the files that actually changed - saving 50-90% bandwidth.',
  live_update_delta_feature1_desc: 'Each file is uploaded and checksummed individually. Devices compare manifests and only download changed files.',
  live_update_delta_feature1_title: 'File-Level Diffing',
  live_update_delta_feature2_desc: "Images, fonts, and videos are downloaded only once. Small code changes don't re-download your entire asset folder.",
  live_update_delta_feature2_title: 'Perfect for Large Assets',
  live_update_delta_feature3_desc: 'Just add --partial to your upload command to enable delta updates for your bundle.',
  live_update_delta_feature3_title: 'Enable with One Flag',
  live_update_delta_title: 'Delta Updates',
  live_update_description: 'Capacitor live updates with channels, rollback, and CLI checks. The EAS Update analog if you have a web app instead of React Native.',
  live_update_dynamic_bullet1_prefix: 'Add an in-app “Update Track” menu: list channels and let testers jump from',
  live_update_dynamic_bullet1_suffix: 'in seconds (no reinstall).',
  live_update_dynamic_bullet2: 'Spin up a pull-request channel per feature, route QA or beta users there, then snap them back to prod when approved.',
  live_update_dynamic_bullet3: 'Run canaries: clone prod to a 10% channel, promote or rollback with a single API call.',
  live_update_dynamic_bullet4: 'Unblock support: move one user to a debug channel that ships extra logging while everyone else stays stable.',
  live_update_dynamic_bullet5: 'Create personal channels for individual users - perfect for debugging specific issues or VIP treatment.',
  live_update_dynamic_bullet6: 'All channel changes are instant - no 24-hour wait, no store approval, no user action required.',
  live_update_dynamic_cta_primary: 'See how channels work',
  live_update_dynamic_cta_secondary: 'Try dynamic channels',
  live_update_dynamic_desc: 'Capgo channels are live controls, not hardcoded. Move users between dev, staging, PR, canary, and production from your app UI or via API instantly.',
