  security_and_compliance: 'Security & Compliance',
  security_questionnaires: 'Security questionnaires',
  security_closing:
    'We strive to resolve all problems as quickly as possible, and we would like to play an active role in the ultimate publication on the problem after it is resolved.',
  security_compliance: 'Security & Compliance',
  security_disclosure_guidelines_1:
    'In order to protect our customers, do not reveal the problem to others until we have researched, addressed and informed our affected customers.',
  security_disclosure_guidelines_2:
    'If you want to publicly share your research about Capgo at a conference, in a blog or any other public forum, you should share a draft with us for review and approval at least 30 days prior to the publication date. Please note that the following should not be included:',
  security_disclosure_guidelines_2_1: 'Data regarding any Capgo customer projects',
  security_disclosure_guidelines_2_2: "Capgo customers' data",
  security_disclosure_guidelines_2_3: 'Information about Capgo employees, contractors or partners',
  security_disclosure_guidelines_title: 'Disclosure guidelines:',
  security_discovery:
    'If you discover a vulnerability, we would like to know about it so we can take steps to address it as quickly as possible. We would like to ask you to help us better protect our clients and our systems.',
  security_intro:
    'At Capgo, we consider the security of our systems a top priority. However, no matter how much effort we put into system security, there can still be vulnerabilities present.',
  security_out_of_scope_1: 'Clickjacking on pages with no sensitive actions.',
  security_out_of_scope_10: 'Deadlinks',
  security_out_of_scope_11: 'User enumeration',
  security_out_of_scope_12:
    'SSRF or DNS spoofing reports against webhooks or website preview. These features run on serverless infrastructure and cannot be used to reach private Capgo infrastructure, so they are not exploitable in our environment.',
  security_out_of_scope_13:
    'User-owned application code or project configuration that Capgo does not own, ship, or control, including files such as capacitor.config.ts, config.capacitor.ts, app source code, and environment-specific settings.',
  security_out_of_scope_14:
    'Access to Capgo bundle files or proof that bundle files can be downloaded. Bundle files are public web assets, users are informed of this, and access to them is not considered a data breach.',
  security_out_of_scope_15:
    'Unauthenticated Capgo plugin/API endpoints that are intentionally public by design — including channel_self set and update/stats endpoints that do not require an API key — are not vulnerabilities. Do not report them as such.',
  security_out_of_scope_16:
    'Uploader or UI incorrectly labeling encryption for bundles served via external_url is not a Capgo vulnerability (encryption of externally hosted bundles is outside Capgo’s control).',
  security_supabase_limitations_title: 'Known Supabase Auth Limitations',
  security_supabase_limitations_intro:
    'Some findings are repeatedly reported and tied to Supabase Auth behavior. These are only treated as Supabase-side issues when they can be reproduced in a shared Supabase demo project configured like ours and when a Supabase configuration change fixes the behavior without changing Capgo security rules. If the fix requires changing Capgo-owned SQL, RPCs, RLS policies, functions, or app logic, that is a Capgo issue and should be reported to us.',
  security_supabase_limitations_1: 'Reports must include a reproducible demo Supabase project, with steps, that matches our settings and demonstrates the behavior.',
  security_supabase_limitations_2:
    'Reports must include the exact fix path: either the Supabase setting/config change that resolves the behavior, or the Capgo-owned code/config object that must change.',
  security_supabase_limitations_3:
    'Account/email flows are validated against the Supabase project settings (for example, whether email verification is disabled and capture flow is used).',
  security_supabase_limitations_4: 'Password and email/password update flows may depend on current Supabase Auth session and re-verification settings.',
  security_supabase_limitations_5:
    'If a demo project proves a concrete Supabase-side fix with no Capgo policy change, or shows a concrete Capgo-owned defect, we review it as actionable.',
  security_out_of_scope_2: 'Unauthenticated/logout/login CSRF.',
  security_out_of_scope_3: "Attacks requiring MITM or physical access to a user's device.",
  security_out_of_scope_4: 'Attacks requiring social engineering.',
  security_out_of_scope_5: 'Any activity that could lead to the disruption of our service (DoS).',
  security_out_of_scope_6: 'Content spoofing and text injection issues without showing an attack vector/without being able to modify HTML/CSS.',
  security_out_of_scope_7: 'Email spoofing',
  security_out_of_scope_8: 'Missing DNSSEC, CAA, CSP headers',
  security_out_of_scope_9: 'Lack of Secure or HTTP only flag on non-sensitive cookies',
  security_out_of_scope_title: 'Out of scope vulnerabilities:',
  security_policy: 'Security Policy',
  security_reporting_guidelines_1: 'Submit your findings through our GitHub Security Advisory:',
  security_reporting_guidelines_2: 'Do provide sufficient information to reproduce the problem, so we will be able to resolve it as quickly as possible.',
  security_reporting_guidelines_3:
    'We accept and review security reports for Capgo plugins, but paid bounties for plugin code are limited to @capgo/capacitor-updater. Other Capgo plugins are free to use and are not part of our paid product offering, so reports for them are reviewed but unpaid.',
  security_reporting_guidelines_title: 'Reporting guidelines:',
  search_plugins_by_name_or_description: 'Search plugins by name or description',
  search_plugins_by_name_or_description_placeholder: 'Search plugins by name or description...',
  security_testing_guidelines_1:
    "Do not run automated scanners on other customer projects. Running automated scanners can run up costs for our users. Aggressively configured scanners might inadvertently disrupt services, exploit vulnerabilities, lead to system instability or breaches and violate Terms of Service from our upstream providers. Our own security systems won't be able to distinguish hostile reconnaissance from whitehat research. If you wish to run an automated scanner, notify us at security@capgo.app and only run it on your own Capgo project. Do NOT attack projects of other customers.",
  security_testing_guidelines_2:
    "Do not take advantage of the vulnerability or problem you have discovered, for example by downloading more data than necessary to demonstrate the vulnerability or deleting or modifying other people's data.",
  security_testing_guidelines_title: 'Testing guidelines:',
  security_txt: 'Security.txt',
  security_what_we_promise_1: 'We will respond to your report within 7 business days with our evaluation of the report and an expected resolution date.',
  security_what_we_promise_2: 'If you have followed the instructions above, we will not take any legal action against you in regard to the report.',
  security_what_we_promise_3: 'We will handle your report with strict confidentiality, and not pass on your personal details to third parties without your permission.',
  security_what_we_promise_4: 'We will keep you informed of the progress towards resolving the problem.',
  security_what_we_promise_5: 'In the public information concerning the problem reported, we will give your name as the discoverer of the problem (unless you desire otherwise).',
  security_what_we_promise_6:
    'If leaked data appears in logs shared with us, we treat it as debugging information used to fix the issue, never as a reason for retaliation or retribution.',
  security_what_we_promise_title: 'What we promise:',
