  solutions_lovable_to_mobile_cta_subtitle: 'Start the 14-day free trial, export your project to GitHub, and request your first iOS and Android builds from the CLI.',
  solutions_lovable_to_mobile_cta_title: 'Put your Lovable app in the stores',
  solutions_lovable_to_mobile_description:
    'Turn a Lovable or vibe-coded web app into iOS and Android apps: export to GitHub, wrap with Capacitor, build with Capgo Build, and ship each Publish as a live update.',
  solutions_lovable_to_mobile_example1_desc: 'Screens, flows, copy, and backend wiring, iterated with prompts. A single-page app gives you a static dist folder to wrap.',
  solutions_lovable_to_mobile_example1_title: 'Lovable builds the web app',
  solutions_lovable_to_mobile_example2_desc:
    'GitHub holds the code. Capacitor puts the built web app into native iOS and Android projects with your app ID, icons, and permissions.',
  solutions_lovable_to_mobile_example2_title: 'Capacitor wraps it',
  solutions_lovable_to_mobile_example3_desc: 'Capgo Build creates signed binaries and uploads them to the stores. Live updates ship later web changes to installed apps.',
  solutions_lovable_to_mobile_example3_title: 'Capgo builds and updates it',
  solutions_lovable_to_mobile_example_label: 'The stack',
  solutions_lovable_to_mobile_example_title: 'What each tool does',
  solutions_lovable_to_mobile_faq1_a:
    'No. Lovable builds the web app. You export it to GitHub, wrap it with Capacitor, and build signed iOS and Android apps with Capgo Build, which uploads them to App Store Connect and Google Play.',
  solutions_lovable_to_mobile_faq1_q: 'Can Lovable publish straight to the App Store?',
  solutions_lovable_to_mobile_faq2_a:
    'No. Capgo Build runs iOS builds on cloud Mac machines. You still need an Apple Developer account for the App Store and a Google Play developer account for Android.',
  solutions_lovable_to_mobile_faq2_q: 'Do I need a Mac or Xcode?',
  solutions_lovable_to_mobile_faq3_a:
    'Yes, for web-layer changes. With GitHub sync on, Publish pushes a commit, a GitHub Action runs bundle upload, and installed apps download the update. New plugins or permissions still need a new store build.',
  solutions_lovable_to_mobile_faq3_q: 'Will changes I make in Lovable reach the mobile app?',
  solutions_lovable_to_mobile_faq4_a: "Yes, with a static export. Point Capacitor's webDir at the out folder instead of dist. Vite single-page apps work as they are.",
  solutions_lovable_to_mobile_faq4_q: 'My Lovable project uses Next.js. Does it work?',
  solutions_lovable_to_mobile_faq5_a:
    'Yes. npx @capgo/cli mcp starts a local MCP server that Claude Code, Codex, or Cursor can use to upload bundles, manage channels, and request builds. Capgo skills add Capgo-specific instructions for the agent.',
  solutions_lovable_to_mobile_faq5_q: 'Can my AI agent handle the release steps?',
  solutions_lovable_to_mobile_faq_desc: 'Short answers for taking a Lovable or vibe-coded app to the App Store and Google Play.',
