  solutions_white_label_badge: 'White-label and multi-tenant apps',
  solutions_white_label_example1_desc: 'Each business customer gets its own logo, theme, onboarding copy, and feature set, and receives updates on its own channel.',
  solutions_white_label_example1_title: 'Customer-branded SaaS app',
  solutions_white_label_example2_desc: 'Each restaurant, clinic, gym, or branch gets local menus, assets, and campaign screens as live updates, without a new binary.',
  solutions_white_label_example2_title: 'Franchise or location app',
  solutions_white_label_example3_desc: 'A host app lists workspaces or mini-apps and moves the device to the matching Capgo channel at runtime with setChannel().',
  solutions_white_label_example3_title: 'Mini-app marketplace',
  solutions_white_label_example_label: 'Common setups',
  solutions_white_label_example_title: 'What white-label looks like in a Capgo app',
  solutions_white_label_faq1_a:
    'Only when each brand has its own app ID in the stores. One store app that serves many tenants is one Capgo app with a channel per tenant. Separate branded store apps are separate Capgo apps, each with its own channels.',
  solutions_white_label_faq1_q: 'Do we need a separate Capgo app for every brand?',
  solutions_white_label_faq2_a:
    "Yes. If the tenant's channel allows self-assignment, call setChannel() from the app. On current plugin versions the choice is stored on the device and used on the next update check.",
  solutions_white_label_faq2_q: 'Can a user switch tenants inside the app?',
  solutions_white_label_faq3_a: 'Use version targeting. Block major updates on a channel, or set a minimum native version on a bundle, so older shells keep a bundle they can run.',
  solutions_white_label_faq3_q: 'What if some tenants are on an older native version?',
  solutions_white_label_faq4_a: "Yes. Each channel keeps its own bundle history. Roll the tenant's channel back to an earlier bundle, and the other channels keep what they have.",
  solutions_white_label_faq4_q: 'Can we roll back one tenant without affecting the others?',
  solutions_white_label_faq5_a:
    'App names, icons, permissions, native plugins, and native code live in the binary. Capgo Build can build each flavor or scheme and upload it to App Store Connect and Google Play.',
  solutions_white_label_faq5_q: 'What still needs a store release?',
  solutions_white_label_faq_desc: 'What teams ask before running many brands on one Capgo setup.',
  solutions_white_label_faq_title: 'White-label questions',
  solutions_white_label_how1_body: 'Each tenant gets a channel with its own bundle and history. Allow self-assignment so the app can move a device onto it.',
  solutions_white_label_how1_title: 'Create a channel for each tenant',
  solutions_white_label_how2_body: "Build the web layer with the tenant's theme and config, then upload it to that tenant's channel only. Other tenants keep their current bundle.",
  solutions_white_label_how2_title: "Upload each tenant's bundle",
  solutions_white_label_how3_body: "After sign-in, call setChannel() with the tenant's channel. The choice is stored on the device and takes effect on the next update check.",
  solutions_white_label_how3_title: 'Move the device to its tenant at sign-in',
  solutions_white_label_how4_body: 'When a tenant needs its own store listing, icon, or permissions, build that flavor or scheme with Capgo Build. No Mac of your own needed.',
  solutions_white_label_how4_title: 'Build branded shells in the cloud',
  solutions_white_label_how_desc: 'One Capacitor codebase, one channel per tenant. The commands and code are from the Capgo CLI and updater docs.',
  solutions_white_label_how_title: 'How white-label teams ship with Capgo',
  solutions_white_label_link_build: 'Build options',
  solutions_white_label_link_builder: 'Capgo Build docs',
  solutions_white_label_link_channels: 'Channels docs',
  solutions_white_label_link_compatibility: 'Native compatibility docs',
  solutions_white_label_link_rollbacks: 'Rollback docs',
  solutions_white_label_link_setchannel: 'setChannel() reference',
  solutions_white_label_link_version_targeting: 'Version targeting docs',
  solutions_white_label_page_cta_subtitle: 'During the 14-day trial, create two tenant channels, upload a bundle to each, and switch a test device between them with setChannel().',
  solutions_white_label_page_cta_title: 'Try tenant channels on your own app',
  solutions_white_label_page_description:
    'Run white-label and multi-tenant Capacitor apps from one codebase: a Capgo channel per tenant, runtime channel switching with setChannel(), version targeting, and cloud builds for each Android flavor and iOS scheme.',
  solutions_white_label_page_h1: "Ship every tenant's app from one codebase",
  solutions_white_label_page_lead:
    "Give each tenant, brand, or location its own Capgo channel. Update one tenant's web layer without touching the others, and build branded native shells with Capgo Build.",
  solutions_white_label_page_title: 'White-Label and Multi-Tenant Capacitor Apps',
  solutions_white_label_pain1_desc:
    'Each customer wants its own logo, theme, feature set, content, and launch date. Separate forks turn those requests into maintenance you pay for on every release.',
  solutions_white_label_pain1_title: 'Brand variants multiply fast',
  solutions_white_label_pain2_desc: 'A menu typo or onboarding fix for one tenant should not wait for a new binary and store review, often 24–48 hours, sometimes much longer.',
  solutions_white_label_pain2_title: 'Store reviews slow tenant fixes',
  solutions_white_label_pain3_desc: 'One global update can break every brand at once. One fork per brand slows the whole team down. You need a release lane per tenant.',
  solutions_white_label_pain3_title: 'Global releases are too blunt',
  solutions_white_label_problem_title: 'White-label apps get hard when every customer becomes a fork',
