  solutions_cordova_to_capacitor_benefit1_desc:
    'Capgo maintains Capacitor plugins for biometrics, social login, SQLite, in-app purchases, in-app browser, background location, and more. They are open source under MPL-2.0.',
  solutions_cordova_to_capacitor_benefit1_title: 'Free replacement plugins',
  solutions_cordova_to_capacitor_benefit2_desc: 'On any Capgo plan, your plugin bug reports and feature requests are handled first by the team that maintains the plugins.',
  solutions_cordova_to_capacitor_benefit2_title: 'Priority plugin fixes',
  solutions_cordova_to_capacitor_benefit3_desc:
    '@capgo/cordova-updater brings Capgo live updates to Cordova iOS 7+ and Android 13+. After the move, keep the same Capgo app ID and channels and switch to the Capacitor plugin.',
  solutions_cordova_to_capacitor_benefit3_title: 'Live updates while still on Cordova',
