  solutions_healthcare_pain1_desc: 'Booking, intake, and reminder screens change often. Each web-layer fix waits for a new binary, store review, and user updates.',
  solutions_healthcare_pain1_title: 'Store review sits between you and the fix',
  solutions_healthcare_pain2_desc: 'Reviewers want to know what the updater sends, where it goes, and whether you can keep it in your own infrastructure.',
  solutions_healthcare_pain2_title: 'Your HIPAA review asks about data flows',
  solutions_healthcare_pain3_desc: 'When a clinician reports an issue, your team has to tell which bundle and native version that device runs.',
  solutions_healthcare_pain3_title: 'Support needs to know which version is live',
  solutions_healthcare_pain4_desc: 'Compliance teams ask who shipped a change, when, and to which channel.',
  solutions_healthcare_pain4_title: 'Every change needs a record',
  solutions_healthcare_reality_label: 'Why care teams add a live update lane',
  solutions_healthcare_reality_title: 'Web-layer fixes should not wait on a new binary',
  solutions_healthcare_scenario_para1: 'A clinician reports a wrong label on a medication or intake screen. The fix is a few lines of JavaScript.',
  solutions_healthcare_scenario_para2: 'With a store-only process, you build a new binary, submit it, and wait. Store review is often 24–48 hours, sometimes much longer.',
  solutions_healthcare_scenario_para3: 'Even after approval, patients and staff still have to install the update before they see the fix.',
  solutions_healthcare_scenario_title: 'The store-only fix path',
  solutions_healthcare_short: 'Healthcare',
  solutions_healthcare_sol1_desc:
    'Upload the fixed JavaScript, HTML, and CSS with the Capgo CLI. By default, devices download the bundle and apply it when the app moves to the background. Native code changes still go through the stores.',
  solutions_healthcare_sol1_title: 'Patch the web layer directly',
  solutions_healthcare_sol2_desc:
    'Capgo Cloud is not presented as a HIPAA-compliant processor for hosted statistics. The updater does not send names, emails, or medical record numbers, and you can limit or move what it does send.',
  solutions_healthcare_sol2_point1: 'EU endpoints for the updater traffic',
  solutions_healthcare_sol2_point2: 'Disable statistics or send them to your own endpoint',
  solutions_healthcare_sol2_point3: 'Licensed self-hosting on Enterprise',
  solutions_healthcare_sol2_title: 'Options for HIPAA reviews',
  solutions_healthcare_sol3_desc:
    'Create a key pair with the CLI. Bundles are encrypted before upload and checked by the app before install. Capgo, storage providers, and CDNs only see ciphertext.',
  solutions_healthcare_sol3_title: 'End-to-end encryption',
  solutions_healthcare_sol4_desc:
    'Send a bundle to a small share of devices, check install and failure data, then increase. Auto-pause can stop a rollout when failures rise, and a bundle that never calls notifyAppReady() is rolled back on the device.',
  solutions_healthcare_sol4_step1: 'First rollout step',
  solutions_healthcare_sol4_step2: 'After checking failures',
  solutions_healthcare_sol4_step3: 'Promoted to all devices',
  solutions_healthcare_sol4_title: 'Staged rollouts and automatic rollback',
  solutions_healthcare_solution_label: 'What Capgo gives healthcare teams',
