  solutions_pr_compare_title: 'Store testing builds vs Capgo PR channels',
  solutions_pr_compare_traditional: 'TestFlight / Play testing',
  solutions_pr_cost_processing_value: 'Every build',
  solutions_pr_dev_benefit1: 'Get device feedback while the PR is still open',
  solutions_pr_dev_benefit2: 'Each push updates the PR channel',
  solutions_pr_dev_benefit3: 'No native build for JavaScript-only changes',
  solutions_pr_faq1_a:
    "Not when the PR only changes the web layer. Reviewers install the app once, and each PR's JavaScript, HTML, CSS, and assets go to its own channel. If the PR adds a plugin or changes native code, it needs a native build. Run build needed in CI to detect that.",
  solutions_pr_faq1_q: 'Do reviewers need a new build for each PR?',
  solutions_pr_faq2_a:
    'Not with an App Preview API key. It can create preview channels, upload bundles, and delete only the channel and bundle it created. It cannot change the default or main channel. In GitHub Actions, run the job on pull_request, not pull_request_target, and limit it to PRs from the same repository.',
  solutions_pr_faq2_q: 'Can the CI key touch our production channel?',
  solutions_pr_faq3_a:
    'An admin enables previews once with app set --preview. After that, get-qr prints a QR code for the PR channel, and --url prints the web preview URL and deep link. Post them in a PR comment.',
  solutions_pr_faq3_q: 'How do reviewers open the preview?',
  solutions_pr_faq4_a:
    'Add a job on the pull request closed event that runs channel delete with --delete-bundle and --success-if-not-found. With an App Preview key, that removes the channel and the bundle linked to it. Bundles from earlier pushes can be removed with bundle cleanup, using a key that has delete rights.',
  solutions_pr_faq4_q: 'What happens to old PR channels and bundles?',
  solutions_pr_faq5_a:
    'Yes. The steps are Capgo CLI commands, so they run in any CI. The docs have integration guides for GitHub Actions, GitLab CI, Bitbucket Pipelines, and Azure DevOps.',
  solutions_pr_faq5_q: 'Does this work with GitLab, Bitbucket, or Azure DevOps?',
  solutions_pr_faq_desc: 'Straight answers for the people who set up CI and the people who review.',
  solutions_pr_faq_title: 'Questions teams ask about PR previews',
  solutions_pr_final_cta_note: '14-day free trial, no credit card. Native changes still need a new build.',
  solutions_pr_final_cta_subtitle: 'Add the upload, QR, and cleanup steps to your CI and try them on your own app during the free trial.',
  solutions_pr_final_cta_title: 'Preview your next pull request on a phone',
  solutions_pr_how1_body:
    'An admin creates an App Preview API key for CI. It can create preview channels and upload bundles, but it cannot change your default or production channel. Previews are turned on once per app.',
  solutions_pr_how1_title: 'Create an App Preview key and enable previews',
  solutions_pr_how2_body:
    'On each push, CI builds the web app and uploads it with a unique bundle version. bundle upload --channel creates the pr-<number> channel if it does not exist and links the bundle to it.',
  solutions_pr_how2_title: 'Upload the PR build to its own channel',
  solutions_pr_how3_body: 'get-qr prints a QR code for the channel, or the preview URLs with --url, so CI can add them to a PR comment.',
  solutions_pr_how3_title: 'Post the preview on the PR',
  solutions_pr_how4_body: 'Run this on the pull request closed event. With an App Preview key, it removes only the channel and linked bundle that key created.',
  solutions_pr_how4_title: 'Delete the channel when the PR closes',
  solutions_pr_how_desc: 'Four CI steps: set up a scoped key once, upload per push, share the preview, clean up on close. Every command below is from the Capgo docs.',
  solutions_pr_how_testers_switch: 'Other ways reviewers switch to a PR channel',
  solutions_pr_how_testers_switch_note:
    'Both need a channel that allows self-assignment. An App Preview key does not set that, so with that key, share the QR preview or set a device override in the console.',
  solutions_pr_how_title: 'How teams preview pull requests with Capgo',
