  solutions_qsr_link_rollbacks: 'Rollbacks docs',
  solutions_qsr_link_rollouts: 'Progressive rollouts docs',
  solutions_qsr_link_update_behavior: 'Update behavior docs',
  solutions_qsr_nightmare_para1: 'A limited-time item goes live on a set date. On launch morning, QA finds that it does not show in the app menu.',
  solutions_qsr_nightmare_para2: 'The fix is in the web layer, but a store-only process means a new binary and store review, which is often 24–48 hours, sometimes much longer.',
  solutions_qsr_nightmare_para3: 'Even after approval, customers still have to install the update, and in-store kiosks need their own update path.',
  solutions_qsr_nightmare_title: 'A launch-day bug on the store-only path',
  solutions_qsr_pain1_desc: 'A limited-time offer starts when the campaign starts. A web-layer fix should not wait for a store release.',
  solutions_qsr_pain1_title: 'Promotions have fixed dates',
  solutions_qsr_pain2_desc: 'Each brand app and each market can need different menus, promotions, and legal text from the same codebase.',
  solutions_qsr_pain2_title: 'Several brands and markets',
