  solutions_solo_ai_benefit1_desc:
    'Run npx @capgo/cli mcp after logging in. The server exposes tools to upload bundles, manage channels, check compatibility, and request native builds.',
  solutions_solo_ai_benefit1_title: 'Capgo MCP server',
  solutions_solo_ai_benefit2_desc: 'Install the open-source Capgo skills so your agent knows the Capgo CLI, live update setup, and release workflows.',
