  solutions_solo_cta_title: 'Try it on your app',
  solutions_solo_description:
    'Live updates and cloud builds for solo Capacitor developers: one CLI, a GitHub Actions step, automatic rollback, iOS builds without a Mac, and an MCP server for your AI assistant. From $12/month billed yearly.',
  solutions_solo_faq1_a: 'Plans start at $12/month billed yearly, or $14 billed monthly. You start with a 14-day free trial, no credit card needed. There is no free plan.',
  solutions_solo_faq1_q: 'How much does Capgo cost for one developer?',
  solutions_solo_faq2_a:
    "No. Capgo Build runs iOS builds on Capgo's Mac machines and can upload the result to App Store Connect. You save your signing credentials once with the CLI.",
  solutions_solo_faq2_q: 'Do I need a Mac to build the iOS app?',
  solutions_solo_faq3_a:
    'If a new bundle does not call notifyAppReady() within 10 seconds, the device goes back to the last working version on its own. Later, you can point the channel back to an earlier bundle.',
  solutions_solo_faq3_q: 'What if a bundle breaks and I am not around?',
  solutions_solo_faq4_a:
    'Yes. Run npx @capgo/cli mcp to start a local MCP server your assistant can call to upload bundles, manage channels, and request builds. The Capgo skills add Capgo-specific instructions to agents like Claude Code, Codex, and Cursor.',
  solutions_solo_faq4_q: 'Can my AI coding assistant use Capgo?',
  solutions_solo_faq5_a:
    'Native code, new native plugins, permissions, and app icons. Those live in the binary and need a store release. Capgo checks bundle compatibility with the native side before upload.',
  solutions_solo_faq5_q: 'What can a live update not change?',
  solutions_solo_faq_desc: 'What people shipping an app on their own ask before trying Capgo.',
  solutions_solo_faq_title: 'Solo developer questions',
