  solutions_use_cases_subtitle: 'Day-to-day release work once live updates are in place. Each card links to the docs.',
  solutions_usecase1_desc: 'A broken checkout or login screen gets a web-layer fix. Upload it and devices pick it up on their next update check.',
  solutions_usecase1_title: 'Critical bug fixes',
  solutions_usecase2_desc: 'Fix wording, update help text, or replace images and other bundled assets without building a new binary.',
  solutions_usecase2_title: 'Copy and content changes',
  solutions_usecase3_desc: 'Compare a new bundle with the previous one: issue-free rate, launch and WebView timing, and deployment markers per version.',
  solutions_usecase3_title: 'Release health in Observe',
  solutions_usecase4_desc: "After you change a channel's bundle, send a silent update notification so devices check now instead of on their next foreground.",
  solutions_usecase4_title: 'Faster pickup with update notifications',
  solutions_usecase5_desc: 'Block major updates on a channel so a bundle that needs new native code never reaches an older binary.',
  solutions_usecase5_title: 'Protect older native builds',
  solutions_usecase6_desc: "Pick any earlier bundle in the channel's History tab to make it live again for every device on that channel.",
  solutions_usecase6_title: 'Roll back from channel history',
  solutions_version_targeting: 'Version Targeting',
  solutions_version_targeting_appflow_badge: 'Appflow migration',
  solutions_version_targeting_appflow_desc: 'Appflow matched live updates to native versions for you. In Capgo you get the same result with channels and version rules:',
  solutions_version_targeting_appflow_step1: 'Create a channel for each native line, for example v1 and v2.',
  solutions_version_targeting_appflow_step2: "Set defaultChannel in each native build's Capacitor config to its channel.",
  solutions_version_targeting_appflow_step3: 'Upload each bundle to the channel of the native line it was built for.',
  solutions_version_targeting_appflow_step4: 'Keep --auto-min-update-version on uploads so a bundle that needs newer native code skips older builds.',
  solutions_version_targeting_appflow_title: 'Coming from Ionic Appflow?',
  solutions_version_targeting_code_label: 'Channel per native line',
  solutions_version_targeting_cta_subtitle: 'Set up the metadata strategy and a compatibility check in CI during the 14-day free trial. No credit card needed.',
  solutions_version_targeting_cta_title: 'Keep every native version on a bundle it can run',
  solutions_version_targeting_description:
    'Keep live updates compatible across native app versions: native compatibility checks, --auto-min-update-version, semver update rules, and a channel per native version.',
  solutions_version_targeting_faq1_a:
    'They keep receiving bundles that are compatible with their native version. With the metadata strategy, a bundle whose minimum native version is above theirs is skipped, and they stay on their current bundle.',
  solutions_version_targeting_faq1_q: 'What happens to users who never update the native app?',
  solutions_version_targeting_faq2_a:
    'No. Version rules only compare version numbers, so a native change shipped in a minor or patch release still goes out. Use --fail-on-incompatible or --auto-min-update-version, which check your native packages.',
  solutions_version_targeting_faq2_q: 'Is --disable-auto-update major enough to prevent crashes?',
  solutions_version_targeting_faq3_a:
    'Run build needed or bundle releaseType against the channel. Both compare native package metadata. They do not see every edit under ios/, android/, or capacitor.config, so gate those paths in git as well.',
  solutions_version_targeting_faq3_q: 'How does CI know whether a change needs a store release?',
  solutions_version_targeting_faq4_a:
    'Yes. Use a channel per native line with defaultChannel, or the metadata strategy with --auto-min-update-version. The Appflow migration guide walks through the setup.',
  solutions_version_targeting_faq4_q: 'We are moving from Ionic Appflow. Can we keep version-matched updates?',
  solutions_version_targeting_faq5_a:
    'Point the channel back to the last compatible bundle from its history, or force the built-in bundle, and ship the native build. notifyAppReady() rolls back a bundle that fails to start, but it is not a substitute for compatible native code.',
  solutions_version_targeting_faq5_q: 'What if an incompatible bundle already went out?',
  solutions_version_targeting_faq_desc: 'For teams supporting users who update the store app at different times.',
  solutions_version_targeting_faq_title: 'Questions about versions in the wild',
  solutions_version_targeting_feature1_desc:
    'bundle compatibility compares the native packages in your project with the bundle live on the channel. Add --fail-on-incompatible in CI to stop an upload that needs a new binary.',
  solutions_version_targeting_feature1_title: 'Check native compatibility before upload',
  solutions_version_targeting_feature2_desc:
    "Put the channel on the metadata strategy and upload with --auto-min-update-version. Devices whose native version is below the bundle's floor skip it and keep their current bundle.",
  solutions_version_targeting_feature2_title: 'Set a native version floor on every bundle',
  solutions_version_targeting_feature3_desc:
    '--disable-auto-update major, minor, or patch keeps a device from receiving a bundle outside its native version line. These rules compare version numbers only. They do not inspect native code.',
  solutions_version_targeting_feature3_title: 'Block updates across semver lines',
  solutions_version_targeting_feature4_desc:
    "Set defaultChannel in each native build's Capacitor config, for example v2 or v3. Each line gets its own bundles, and an older line can stay on its last working bundle.",
  solutions_version_targeting_feature4_title: 'A channel per native version',
  solutions_version_targeting_hero_subtitle:
    "Users update from the store at their own pace, so several native versions of your app are live at once. Capgo checks each bundle's native dependencies, blocks updates by version rules, and can route each native version to its own channel.",
  solutions_version_targeting_hero_title: 'Send each native version only the bundles it can run',
  solutions_version_targeting_how1_body:
    'build needed compares your native packages with the channel. It prints yes and exits with code 1 when a store release is required, and no when a live update is enough.',
  solutions_version_targeting_how1_title: 'Ask whether the commit needs a native build',
  solutions_version_targeting_how2_body: 'Do this once. From then on, each bundle carries a minimum native version and devices below it skip the bundle.',
  solutions_version_targeting_how2_title: 'Switch the channel to the metadata strategy',
  solutions_version_targeting_how3_body:
    'Keep --auto-min-update-version on every upload. --fail-on-incompatible stops the job if the bundle needs native code the channel does not have.',
  solutions_version_targeting_how3_title: 'Upload everyday live updates',
  solutions_version_targeting_how4_body:
    'When the new binary ships, upload its bundle without --fail-on-incompatible. Capgo raises the floor so older builds skip it, and later checks compare against the new native packages.',
  solutions_version_targeting_how4_title: 'Upload the bundle for a new native release',
  solutions_version_targeting_how_desc: 'A CI setup that lets the live update lane and the store lane work side by side. Every command below is from the Capgo CLI docs.',
  solutions_version_targeting_how_title: 'How teams with several native versions ship with Capgo',
