  store_policy_apple_body:
    "Apps may download interpreted code if it doesn't change the app's primary purpose, create a storefront for other code or apps, or bypass signing, the sandbox, or other OS security features.",
  store_policy_apple_label: 'Apple Developer Program License Agreement',
  store_policy_eyebrow: 'App Store & Google Play',
  store_policy_faq_cta: 'Read the store policy FAQ',
  store_policy_google_body:
    "Apps can't update their own native code outside Google Play. Code that runs in an interpreter or virtual machine, such as JavaScript in a WebView, is explicitly exempt.",
  store_policy_google_label: 'Google Play Device and Network Abuse policy',
  store_policy_incident_body:
    "Our splash screen auto-hide feature linked at runtime to the separate splash screen plugin. Apple's review flagged that dynamic linking as a dynamic code concern. It was unrelated to OTA updates, and we removed the dynamic link from the plugin.",
  store_policy_incident_label: 'Has Apple ever flagged Capgo?',
  store_policy_lead:
    'Not for using live updates. Both stores let apps download interpreted code like JavaScript, HTML, and CSS, as long as each update stays within the app you submitted for review.',
  store_policy_note: 'Review decisions always belong to Apple and Google, so no vendor can promise approval. Capgo keeps you on the side of the policies they publish.',
  store_policy_official_link: 'Official policy',
  store_policy_record_body: 'Across {apps} apps in production, we have never seen a store reject an app because it ships updates with Capgo.',
  store_policy_record_label: 'Our track record',
  store_policy_record_value: '0 rejections',
  store_policy_rule_native: 'Send native code, permissions, and plugin changes through a store release.',
  store_policy_rule_ota: 'Ship web-layer changes over the air: JavaScript, HTML, CSS, and assets.',
  store_policy_rule_purpose: 'Keep every update within the purpose you submitted for review.',
  store_policy_rules_label: 'Stay inside the rules',
  store_policy_title: 'Will Apple or Google reject OTA updates?',
